using System.Collections.Generic;
using CP.ProRoad;
using UnityEditor;
using UnityEngine;

namespace ProRoadMeshTools {

	/// <summary>
	/// ProRoadが生成したメッシュの法線を再計算します。
	/// Recalculates normals for meshes generated by ProRoad.
	/// </summary>
	internal static class ProRoadMeshNormalUtility {

		/// <summary>
		/// メッシュ法線再計算の処理件数とスキップ件数を保持します。
		/// Stores the processed and skipped counts from mesh normal recalculation.
		/// </summary>
		internal readonly struct ProcessResult {

			internal readonly int ProcessedCount;
			internal readonly int SkippedCount;

			/// <summary>
			/// 処理件数とスキップ件数から結果を作成します。
			/// Creates a result from the processed and skipped counts.
			/// </summary>
			internal ProcessResult( int _processedCount, int _skippedCount ) {
				ProcessedCount = _processedCount;
				SkippedCount = _skippedCount;
			}
		}

		/// <summary>
		/// 指定されたProRoadが共有する生成メッシュの法線を重複なく再計算します。
		/// Recalculates normals once for each generated mesh shared by the specified ProRoad components.
		/// </summary>
		internal static ProcessResult RecalculateRoadMeshNormals( IEnumerable<ProRoad> _roads ) {
			List<Mesh> meshes = new List<Mesh>( );
			foreach ( ProRoad road in _roads ) {
				if ( road == null ) continue;

				Transform meshesParent = road.transform.Find( "Meshes" );
				if ( meshesParent == null ) continue;

				MeshFilter[ ] meshFilters = meshesParent.GetComponentsInChildren<MeshFilter>( true );
				foreach ( MeshFilter meshFilter in meshFilters ) meshes.Add( meshFilter.sharedMesh );
			}

			ProcessResult result = RecalculateMeshes( meshes );
			Debug.Log( $"Recalculated ProRoad mesh normals: {result.ProcessedCount} / skipped: {result.SkippedCount}" );
			return result;
		}

		/// <summary>
		/// 読み取り可能な各メッシュの法線を重複なく再計算します。
		/// Recalculates normals once for each readable mesh.
		/// </summary>
		private static ProcessResult RecalculateMeshes( IEnumerable<Mesh> _meshes ) {
			HashSet<Mesh> seenMeshes = new HashSet<Mesh>( );
			int processedCount = 0;
			int skippedCount = 0;
			foreach ( Mesh mesh in _meshes ) {
				if ( mesh == null || !seenMeshes.Add( mesh ) ) continue;
				if ( !mesh.isReadable ) {
					Debug.LogWarning( "Cannot recalculate normals because the mesh is not readable: " + mesh.name, mesh );
					skippedCount++;
					continue;
				}

				Undo.RegisterCompleteObjectUndo( mesh, "Recalculate ProRoad Mesh Normals" );
				mesh.RecalculateNormals( );
				EditorUtility.SetDirty( mesh );
				processedCount++;
			}

			AssetDatabase.SaveAssets( );
			return new ProcessResult( processedCount, skippedCount );
		}
	}
}
